"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3544],{82446:e=>{e.exports=JSON.parse('{"functions":[{"name":"childrenOf","desc":"The children of an instance, memoized.\\n\\nPrefab hierarchies are static, so the same template is walked identically on\\nevery clone.\\n\\nKeyed weakly, so a prefab the game destroys is not pinned in memory by its\\nown cache entry.","params":[{"name":"instance","desc":"","lua_type":"Instance"}],"returns":[{"desc":"","lua_type":"{ Instance }"}],"function_type":"static","private":true,"source":{"line":72,"path":"src/main/shared/utils/slowClone.luau"}},{"name":"enqueue","desc":"Queues a hierarchy to be copied and returns its root immediately.\\n\\nThe returned root is detached and initially childless; it gains its contents\\nover the following frames. `onComplete` fires once, deferred, when the last\\nnode has been copied.","params":[{"name":"template","desc":"Source hierarchy. Not modified.","lua_type":"Instance"},{"name":"onComplete","desc":"Called with the finished root.","lua_type":"(Instance) -> ()"}],"returns":[{"desc":"The detached root clone.","lua_type":"Instance"}],"function_type":"static","source":{"line":93,"path":"src/main/shared/utils/slowClone.luau"}},{"name":"processNext","desc":"Copies nodes until the deadline passes, oldest job first.\\n\\nAlways copies at least one node per call, so a frame that is already over\\nbudget still makes progress rather than deadlocking the queue.","params":[{"name":"deadline","desc":"`os.clock()` value to stop at.","lua_type":"number"}],"returns":[{"desc":"Nodes copied.","lua_type":"number"}],"function_type":"static","source":{"line":119,"path":"src/main/shared/utils/slowClone.luau"}},{"name":"clear","desc":"Drops every queued job. Their roots are left detached and unfinished, so the\\ncaller is responsible for destroying anything it still holds.","params":[],"returns":[],"function_type":"static","source":{"line":170,"path":"src/main/shared/utils/slowClone.luau"}}],"properties":[],"types":[{"name":"Chunk","desc":"One parent and the children still owed to it.\\n\\nWork is tracked as flat chunks rather than by recursing, because recursion\\ncannot be paused half way down a tree.","fields":[{"name":"sources","lua_type":"{ Instance }","desc":"Nodes still to copy."},{"name":"parent","lua_type":"Instance","desc":"Where their copies go."},{"name":"head","lua_type":"number","desc":"Next source index, 1-based."}],"source":{"line":35,"path":"src/main/shared/utils/slowClone.luau"}},{"name":"Job","desc":"One hierarchy part-way through being copied.","fields":[{"name":"rootClone","lua_type":"Instance","desc":"The detached root, handed to the caller at enqueue time."},{"name":"chunks","lua_type":"{ Chunk }","desc":"Outstanding work, appended to as nested children are discovered."},{"name":"chunkHead","lua_type":"number","desc":"Next chunk index, 1-based."},{"name":"onComplete","lua_type":"(Instance) -> ()","desc":"Called once the whole hierarchy has been copied."}],"source":{"line":47,"path":"src/main/shared/utils/slowClone.luau"}}],"name":"slowClone","desc":"Clones a hierarchy one node at a time instead of all at once.\\n\\n`Instance:Clone()` deep-copies an entire subtree in a single uninterruptible\\ncall \u2014 a 272-part house is one spike you cannot break up. `Instance.fromExisting`\\ncopies exactly one node and none of its children, which turns the same work\\ninto a queue that can be stopped at any point and resumed next frame.\\n\\nNothing produced here is parented. A job hands back its detached root\\nimmediately and fills it in over subsequent frames, so a half-built clone\\nnever costs the engine anything. Use [slowParent] to stream it into the world\\nafterwards.\\n\\nAdapted from the `feat/better-maze-generation` prototype, with the budget\\nchanged from a private microsecond allowance to the pipeline\'s shared frame\\ndeadline.","tags":["shared-util"],"source":{"line":22,"path":"src/main/shared/utils/slowClone.luau"}}')}}]);